# --- 인가표 ---

@SpringBootTest
@AutoConfigureMockMvc
class AuthorizationMatrixTest {

    static Stream<Arguments> matrix() {
        return Stream.of(
            Arguments.of("GET",    "/about",         "ANON",    200),
            Arguments.of("GET",    "/orders",        "ANON",    302),
            Arguments.of("GET",    "/orders",        "USER",    200),
            Arguments.of("GET",    "/report/x",      "USER",    403),
            Arguments.of("GET",    "/report/x",      "MANAGER", 200),
            Arguments.of("GET",    "/admin/panel",   "MANAGER", 403),
            Arguments.of("GET",    "/admin/panel",   "ADMIN",   200),
            Arguments.of("GET",    "/api/v1/orders", "ANON",    401),
            Arguments.of("DELETE", "/api/v1/orders/1", "USER",  403),
            Arguments.of("DELETE", "/api/v1/orders/1", "ADMIN", 200),
            Arguments.of("GET",    "/internal/dump", "ADMIN",   403));
    }

    @ParameterizedTest(name = "{0} {1} as {2} -> {3}")
    @MethodSource("matrix")
    void 인가표(String method, String path, String role, int expected)
            throws Exception {
        var request = request(HttpMethod.valueOf(method), path).with(csrf());
        if (!"ANON".equals(role)) {
            request = request.with(user("someone@a.com").roles(role));
        }
        mockMvc.perform(request).andExpect(status().is(expected));
    }
}

