#   내가 적은 권한을 그대로 준다

#   둘을 다 써야 하는 이유다

# --- 빠진 엔드포인트 훑기 ---

@Test
void 모든_엔드포인트가_인가표에_있다() {
    Set<String> tested = AuthorizationMatrixTest.matrix()
            .map(a -> a.get()[1].toString())
            .collect(Collectors.toSet());

    List<String> missing = new ArrayList<>();
    handlerMapping.getHandlerMethods().forEach((info, method) -> {
        for (String pattern : info.getPathPatternsCondition().getPatternValues()) {
            boolean covered = tested.stream()
                    .anyMatch(t -> new AntPathMatcher().match(pattern, t));
            if (!covered) missing.add(pattern);
        }
    });

    System.out.println(">>> 안 덮인 경로 " + missing.size() + "개");
    missing.forEach(m -> System.out.println("    " + m));
    assertThat(missing).isEmpty();
}

